  const dateTime = (d) => { const x = new Date(d); return Number.isNaN(x.getTime()) ? null : x; };
  const thaiDate = (iso, options = {}) => { const d = dateTime(`${iso}T12:00:00`); return d ? new Intl.DateTimeFormat('th-TH', { day:'numeric', month:'short', year:'numeric', ...options }).format(d) : '—'; };
  const timeText = (iso) => { const d = dateTime(iso); return d ? new Intl.DateTimeFormat('th-TH', { timeZone:'Asia/Bangkok', hour:'2-digit', minute:'2-digit', hour12:false }).format(d) : '—'; };
  const escapeHTML = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
