  attendance.forEach(record=>{if(record.id==='sample-att-1'||record.id==='sample-att-2')record.checkOut=null;});
  // ทิ้งรายการที่ผิดรูปแบบเพื่อให้หน้าจอทำงานต่อได้
  employees = employees.filter(e => e && typeof e === 'object' && e.id && e.code && e.name).map(e => ({id:String(e.id),code:String(e.code),name:String(e.name),department:['DEMO-019','DEMO-020','DEMO-021'].includes(String(e.code))||e.department==='การเงิน'?'บัญชี':e.department==='ทรัพยากรบุคคล'?'HR':String(e.department||''),position:String(e.position||''),workStart:validTime(e.workStart)?e.workStart:'',workEnd:validTime(e.workEnd)?e.workEnd:'',shiftName:String(e.shiftName||''),workMode:e.workMode==='WFH'?'WFH':'สำนักงาน',company:String(e.company||'บริษัทหลัก'),status:e.status === 'inactive' ? 'inactive' : 'active'}));
