    const checkoutBeforeCheckin=parsedOut&&(()=>{const input=dateTime(checkIn),out=parsedOut;return out< input || (out.getHours()*60+out.getMinutes()<input.getHours()*60+input.getMinutes()&&out.toDateString()===input.toDateString());})();
    const checkOut=parsedOut&&!checkoutBeforeCheckin?String(a.checkOut):null;
