    return {id:String(a.id),employeeId:String(a.employeeId),employeeCode:String(a.employeeCode||''),employeeName:String(a.employeeName||''),department:String(a.department||''),workStart:typeof a.workStart==='string'?a.workStart:null,workEnd:typeof a.workEnd==='string'?a.workEnd:'',date:String(a.date),checkIn,checkOut,lateReason:String(a.lateReason||''),hrNotifiedAt:String(a.hrNotifiedAt||'')};
