  function saveAll(){ try { localStorage.setItem(EMP_KEY,JSON.stringify(employees)); localStorage.setItem(ATT_KEY,JSON.stringify(attendance)); localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings)); localStorage.setItem(LEAVE_KEY,JSON.stringify(leaves)); localStorage.setItem('worktime_leave_quota_v1',String(leaveQuota)); return true; } catch { showToast('บันทึกข้อมูลไม่สำเร็จ กรุณาตรวจสอบพื้นที่จัดเก็บของเบราว์เซอร์',true); return false; } }
  if(invalidCheckout)saveAll();
  function validTime(value){if(!/^\d\d:\d\d$/.test(value||''))return false;const [h,m]=value.split(':').map(Number);return h>=0&&h<=23&&m>=0&&m<=59;}
  function showToast(msg,error=false){const t=$('#toast');t.textContent=msg;t.classList.toggle('error',error);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
  function employee(id){return employees.find(e=>e.id===id);}
  function historicalEmployee(record){const e=employee(record.employeeId);return e||{code:record.employeeCode||'—',name:record.employeeName||'พนักงานที่ถูกลบ',department:record.department||'—',position:''};}
  function dayRecords(day,empId){return attendance.filter(a=>a.date===day&&(!empId||a.employeeId===empId)).sort((a,b)=>a.checkIn.localeCompare(b.checkIn));}
  function currentRecord(id,day=todayISO()){const all=dayRecords(day,id);return all[all.length-1]||null;}
  function openRecord(id){return attendance.filter(a=>a.employeeId===id&&!a.checkOut).sort((a,b)=>b.checkIn.localeCompare(a.checkIn))[0]||null;}
  function statusFor(record){return !record?'ยังไม่เข้างาน':record.checkOut?'ออกงานแล้ว':'กำลังทำงาน';}
  function isLate(record){if(!record?.checkIn)return false;const threshold=record.workStart||settings.workStart;const t=dateTime(record.checkIn);if(!threshold||!t)return false;const [h,m]=threshold.split(':').map(Number),grace=Number.isFinite(Number(settings.lateGrace))?Number(settings.lateGrace):0;return t.getHours()*60+t.getMinutes()>h*60+m+grace;}
  function timeCell(record,type){const value=type==='in'?record?.checkIn:record?.checkOut;const cls=type==='in'&&isLate(record)?'time-late':type==='in'&&!value?'time-missing':type==='out'&&value?'time-done':'';return `<span class="${cls}">${type==='out'&&!value?'-':escapeHTML(timeText(value))}</span>`;}
  function effectiveShift(e){return settings.departmentShifts?.[e?.department]||{workStart:e?.workStart||settings.workStart,workEnd:e?.workEnd||settings.workEnd,shiftName:e?.shiftName||'กะประจำแผนก'};}
  function resolvedStart(e){return effectiveShift(e).workStart;}
  function shiftLabel(e){const shift=effectiveShift(e),time=shift.workStart&&shift.workEnd?`${shift.workStart}–${shift.workEnd}`:shift.workStart?`เริ่ม ${shift.workStart} · ไม่ระบุเวลาเลิก`:shift.workEnd?`ไม่ระบุเวลาเริ่ม · เลิก ${shift.workEnd}`:`มาตรฐาน ${settings.workStart}–${settings.workEnd}`;return `${shift.shiftName?`${shift.shiftName} · `:''}${time} · ${e.workMode||'สำนักงาน'}`;}
  function shiftHours(e){const shift=effectiveShift(e);return `${shift.workStart||settings.workStart}–${shift.workEnd||settings.workEnd}`;}
  function renderDepartmentShifts(){const body=$('#departmentShiftBody');if(!body)return;const departments=[...new Set(employees.map(e=>e.department).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'th'));body.replaceChildren();departments.forEach(department=>{const members=employees.filter(e=>e.department===department),saved=settings.departmentShifts?.[department],start=saved?.workStart||members.find(e=>e.workStart)?.workStart||settings.workStart,end=saved?.workEnd||members.find(e=>e.workEnd)?.workEnd||settings.workEnd,name=saved?.shiftName||members.find(e=>e.shiftName)?.shiftName||'กะประจำแผนก',tr=document.createElement('tr');tr.dataset.department=department;tr.innerHTML=`<td><b>${escapeHTML(department)}</b></td><td><input aria-label="ชื่อกะ ${escapeHTML(department)}" data-shift-name value="${escapeHTML(name)}" maxlength="40"></td><td><input aria-label="เวลาเข้างาน ${escapeHTML(department)}" data-shift-start type="time" required value="${escapeHTML(start)}"></td><td><input aria-label="เวลาออกงาน ${escapeHTML(department)}" data-shift-end type="time" required value="${escapeHTML(end)}"></td><td>${members.length} คน</td>`;body.append(tr);});}
  function statusLabel(record){return `${statusFor(record)}${isLate(record)?' · มาสาย':''}`;}
  function statusClass(status){return status.includes('มาสาย')?'status-late':status==='กำลังทำงาน'?'status-working':status==='ออกงานแล้ว'?'status-done':status==='ปฏิบัติงาน'?'status-active':status==='ไม่ปฏิบัติงาน'?'status-inactive':'status-absent';}
  function duration(rec){if(!rec?.checkIn||!rec?.checkOut)return '—';let start=dateTime(rec.checkIn),end=dateTime(rec.checkOut);if(!start||!end)return '—';if(end<start)end=new Date(end.getTime()+86400000);const mins=Math.floor((end-start)/60000);return `${Math.floor(mins/60)} ชม. ${mins%60} นาที`;}
  function durationMinutes(rec){if(!rec?.checkIn||!rec?.checkOut)return 0;let a=dateTime(rec.checkIn),b=dateTime(rec.checkOut);if(!a||!b)return 0;if(b<a)b=new Date(b.getTime()+86400000);return Math.max(0,Math.floor((b-a)/60000));}
