  function fillSelect(select,items,placeholder,selected=''){if(!select)return;const old=selected||select.value;select.replaceChildren(new Option(placeholder,''));items.forEach(x=>select.add(new Option(`${x.code} · ${x.name}`,x.id)));if(items.some(x=>x.id===old))select.value=old;}
  function updateQuickEmployeeOptions(){const department=$('#quickDepartment').value,previous=$('#quickEmployee').value,select=$('#quickEmployee'),list=employees.filter(e=>e.status==='active'&&department&&e.department===department);select.replaceChildren(new Option(department?'เลือกพนักงาน':'เลือกแผนกก่อน',''));list.forEach(e=>select.add(new Option(`${e.code} · ${e.name}`,e.id)));select.disabled=!department||!list.length;if(list.some(e=>e.id===previous))select.value=previous;else select.value='';}
  function refreshSelects(){const active=employees.filter(e=>e.status==='active');const quickDepartment=$('#quickDepartment'),currentDepartment=quickDepartment.value,deps=[...new Set(employees.map(e=>e.department).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'th'));quickDepartment.replaceChildren(new Option('เลือกแผนก',''));deps.forEach(d=>quickDepartment.add(new Option(d,d)));if(deps.includes(currentDepartment))quickDepartment.value=currentDepartment;updateQuickEmployeeOptions();fillSelect($('#attendanceEmployee'),active,'เลือกรหัสพนักงาน');fillSelect($('#filterEmployee'),employees,'ทุกคน');for(const id of ['filterDepartment','employeeDepartmentFilter','reportDepartment']){const dep=$('#'+id),value=dep.value;dep.replaceChildren(new Option('ทุกแผนก',''));deps.forEach(d=>dep.add(new Option(d,d)));if(deps.includes(value))dep.value=value;}}
  function employeeDecisionNotices(){if(!activeUserId||isHRSession())return[];return leaves.filter(x=>x.employeeId===activeUserId&&(x.status==='อนุมัติ'||x.status==='ไม่อนุมัติ')).map(x=>({id:'leave-decision:'+x.id+':'+(x.reviewedAt||x.status),type:x.type,status:x.status,title:x.status==='อนุมัติ'?'HR อนุมัติคำขอของคุณแล้ว':'HR ไม่อนุมัติคำขอของคุณ',dates:thaiDate(x.start)+' – '+thaiDate(x.end),detail:x.status==='อนุมัติ'?'HR อนุมัติคำขอ '+x.type+' ของคุณแล้ว.':('HR ไม่อนุมัติคำขอ '+x.type+' ของคุณ.'+(x.reviewReason?' เหตุผล: '+x.reviewReason:'')),when:x.reviewedAt||x.createdAt,reviewReason:x.reviewReason||''})).sort((a,b)=>String(b.when||'').localeCompare(String(a.when||'')));}
  function renderEmployeeNotifications(){const bell=$('#employeeNotificationBell'),list=$('#employeeNotificationList');if(!bell||!list)return;const items=employeeDecisionNotices(),read=new Set(employeeNoticeReads[activeUserId]||[]),unread=items.filter(x=>!read.has(x.id)).length;$('#employeeNotificationBadge').textContent=unread>99?'99+':String(unread);$('#employeeNotificationBadge').hidden=unread===0;$('#employeeNotificationSummary').textContent=items.length+' รายการ'+(unread?' · ใหม่ '+unread:'');list.replaceChildren();items.forEach(item=>{const button=document.createElement('button');button.type='button';button.className='notification-item'+(read.has(item.id)?'':' unread');button.dataset.employeeNoticeId=item.id;button.innerHTML='<b>'+escapeHTML(item.title)+'</b><span>'+escapeHTML(item.type+' · '+item.dates)+'</span><small>'+escapeHTML(item.when?thaiDate(String(item.when).slice(0,10)):'')+'</small>';list.append(button);});$('#employeeNotificationEmpty').hidden=items.length>0;}
  function toggleEmployeeNotifications(){const panel=$('#employeeNotificationPopover'),button=$('#employeeNotificationBell');panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));}
  function openEmployeeNotificationDetail(id){const item=employeeDecisionNotices().find(x=>x.id===id);if(!item)return;employeeNoticeReads[activeUserId]=[...new Set([...(employeeNoticeReads[activeUserId]||[]),item.id])];try{localStorage.setItem(EMPLOYEE_NOTICE_READ_KEY,JSON.stringify(employeeNoticeReads));}catch{}renderEmployeeNotifications();$('#employeeNotificationDetailTitle').textContent=item.title;$('#employeeNotificationDetailDate').textContent=item.dates+' · '+item.type;$('#employeeNotificationDetailText').textContent=item.detail;$('#employeeNotificationDetailDialog').showModal();}
  function renderClock(){const now=new Date();$('#clockDate').textContent=new Intl.DateTimeFormat('th-TH',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(now);$('#clockTime').textContent=new Intl.DateTimeFormat('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);$('#todayLabel').textContent=new Intl.DateTimeFormat('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);$('#attendanceClock').textContent=new Intl.DateTimeFormat('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);$('#attendanceDate').textContent=$('#todayLabel').textContent;}
  function renderDemoLogin(){const departmentSelect=$('#demoLoginDepartment'),selectedDepartment=departmentSelect.value;const departments=[...new Set([...employees.filter(e=>e.status==='active').map(e=>e.department),...demoEmployees.map(([department])=>department)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'th'));departmentSelect.replaceChildren(new Option('เลือกแผนก',''));departments.forEach(d=>departmentSelect.add(new Option(d,d)));if(departments.includes(selectedDepartment))departmentSelect.value=selectedDepartment;updateDemoLoginNames();}
  function updateDemoLoginNames(){const department=$('#demoLoginDepartment').value,select=$('#demoLoginEmployee'),selected=select.value;select.replaceChildren(new Option(department?'เลือกชื่อ':'เลือกแผนกก่อน',''));if(department==='HR'){select.add(new Option(`${DEMO_HR.name} · HR`,DEMO_HR_ID));}else employees.filter(e=>e.status==='active'&&e.department===department).forEach(e=>select.add(new Option(`${e.name} · พนักงาน`,e.id)));select.disabled=!department;if(department==='HR'&&selected===DEMO_HR_ID)select.value=selected;else if(department!=='HR'&&employees.some(e=>e.id===selected&&e.department===department))select.value=selected;else select.value='';}
