  function startDemoSession(id){const hr=id===DEMO_HR_ID,e=employee(id);if(!e||e.status!=='active'){showToast('กรุณาเลือกบัญชีสาธิตที่ต้องการเข้าสู่ระบบ',true);return;}activeUserId=id;localStorage.setItem('worktime_demo_user',JSON.stringify(activeUserId));$('#demoLogin').hidden=true;$('#appShell').hidden=false;applyRoleNavigation();renderEmployeeHome();renderLeaves();navigate('employeeHome');}
  function renderDashboard(){const day=todayISO(), records=dayRecords(day);const presentIds=new Set(records.map(r=>r.employeeId)),workingIds=new Set(attendance.filter(r=>!r.checkOut).map(r=>r.employeeId)),doneIds=new Set(records.filter(r=>r.checkOut).map(r=>r.employeeId));$('#statEmployees').textContent=employees.length;$('#statPresent').textContent=presentIds.size;$('#statAbsent').textContent=Math.max(0,employees.length-presentIds.size);$('#statWorking').textContent=workingIds.size;$('#statDone').textContent=doneIds.size;const rows=[...attendance].sort((a,b)=>b.checkIn.localeCompare(a.checkIn)).slice(0,6);const body=$('#recentBody');body.replaceChildren();rows.forEach(r=>{const e=historicalEmployee(r),tr=document.createElement('tr');tr.innerHTML=`<td>${personMarkup(e,`กะ ${shiftHours(e)}`)}</td><td>${escapeHTML(e.department||'—')}</td><td>${escapeHTML(thaiDate(r.date))}</td><td>${timeCell(r,'in')}</td><td>${timeCell(r,'out')}</td><td><span class="status-pill ${statusClass(statusLabel(r))}">${escapeHTML(statusLabel(r))}</span></td>`;body.append(tr);});$('#recentEmpty').hidden=rows.length>0;renderHRNotices();updateQuickPreview();}
  function renderHRNotices(){const list=attendance.filter(r=>r.hrNotifiedAt).sort((a,b)=>b.hrNotifiedAt.localeCompare(a.hrNotifiedAt)),body=$('#hrNoticeList');body.replaceChildren();list.forEach(r=>{const e=historicalEmployee(r),item=document.createElement('article');item.className='hr-notice-item';item.innerHTML=`<div class="hr-notice-meta"><b>${escapeHTML(e.name)}</b><span>แผนก: ${escapeHTML(e.department||'—')} · ${escapeHTML(thaiDate(r.date))} ${escapeHTML(timeText(r.hrNotifiedAt))}</span></div><p>${escapeHTML(r.lateReason||'ไม่ระบุเหตุผล')}</p>`;body.append(item);});$('#hrNoticeCount').textContent=`${list.length} รายการ`;$('#hrNoticeEmpty').hidden=list.length>0;}
  function sendLateNotice(id,note){const e=employee(id),r=currentRecord(id),reason=String(note||r?.lateReason||'').trim();if(!e){showToast('กรุณาเข้าสู่ระบบพนักงานก่อนส่งข้อความ',true);return;}if(!r){showToast('กรุณาลงเวลาเข้างานก่อนส่งแจ้ง HR',true);return;}if(!reason){showToast('กรุณาระบุเหตุผลที่มาสายก่อนส่งแจ้ง HR',true);return;}r.lateReason=reason;r.hrNotifiedAt=new Date().toISOString();if(saveAll()){renderAll();showToast('ส่งข้อความแจ้ง HR แล้ว');}}
  function updateQuickPreview(){const id=$('#quickEmployee').value,e=employee(id),r=e?currentRecord(id):null,open=e?openRecord(id):null,btnIn=$('#quickIn'),btnOut=$('#quickOut');if(!e){$('#quickEmployeeInfo').textContent=$('#quickDepartment').value?'เลือกพนักงานเพื่อเริ่มลงเวลา':'เลือกแผนกและพนักงานเพื่อเริ่มลงเวลา';btnIn.disabled=true;btnOut.disabled=true;return;}$('#quickEmployeeInfo').innerHTML=`<b>${escapeHTML(e.name)}</b><span>${escapeHTML(e.department)} · ${escapeHTML(e.position)} · ${escapeHTML(shiftLabel(e))}</span>`;btnIn.disabled=!!open||!!r;btnOut.disabled=!open;}
  function updateAttendancePreview(){const id=$('#attendanceEmployee').value,e=employee(id),r=e?(openRecord(id)||currentRecord(id)):null;const p=$('#attendancePreview');p.replaceChildren();const av=document.createElement('div');av.className='preview-avatar';av.textContent=e?initials(e.name):'?';const info=document.createElement('div');const b=document.createElement('b'),s=document.createElement('small');b.textContent=e?e.name:'ยังไม่ได้เลือกพนักงาน';s.textContent=e?`${e.code} · ${e.department} · ${shiftLabel(e)}`:'ข้อมูลการลงเวลาวันนี้จะแสดงที่นี่';info.append(b,s);p.append(av,info);$('#todayIn').textContent=r?timeText(r.checkIn):'—';$('#todayOut').textContent=r?.checkOut?timeText(r.checkOut):'—';$('#todayStatus').textContent=e?statusFor(r):'รอเลือกพนักงาน';$('#attendanceIn').disabled=!e||!!openRecord(id)||!!currentRecord(id);$('#attendanceOut').disabled=!openRecord(id);}
  function renderEmployees(){const query=$('#employeeSearch').value.trim().toLocaleLowerCase('th'),dept=$('#employeeDepartmentFilter').value,status=$('#employeeStatusFilter').value;const list=employees.filter(e=>(!query||[e.name,e.code,e.department,e.position].some(v=>v.toLocaleLowerCase('th').includes(query)))&&(!dept||e.department===dept)&&(!status||e.status===status));const body=$('#employeesBody');body.replaceChildren();list.forEach(e=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${personMarkup(e)}</td><td><b>${escapeHTML(e.code)}</b></td><td>${escapeHTML(e.department)}</td><td>${escapeHTML(e.position)}</td><td>${escapeHTML(shiftLabel(e))}</td><td><span class="status-pill ${statusClass(e.status==='active'?'ปฏิบัติงาน':'ไม่ปฏิบัติงาน')}">${e.status==='active'?'ปฏิบัติงาน':'ไม่ปฏิบัติงาน'}</span></td><td><div class="action-buttons"><button class="mini-action" data-edit="${escapeHTML(e.id)}">แก้ไข</button><button class="mini-action delete" data-delete="${escapeHTML(e.id)}">ลบ</button></div></td>`;body.append(tr);});$('#employeeCount').textContent=`${list.length} คน`;$('#employeesEmpty').hidden=list.length>0;}
  function filterHistory(){const q=$('#historySearch').value.trim().toLocaleLowerCase('th'),day=$('#filterDate').value,end=$('#filterEndDate').value,dep=$('#filterDepartment').value,empId=$('#filterEmployee').value;return [...attendance].filter(r=>{const e=historicalEmployee(r),hay=`${e.name} ${e.code} ${e.department}`.toLocaleLowerCase('th');return(!q||hay.includes(q))&&(!day||r.date>=day)&&(!end||r.date<=end)&&(!dep||e.department===dep)&&(!empId||r.employeeId===empId);}).sort((a,b)=>b.date.localeCompare(a.date)||b.checkIn.localeCompare(a.checkIn));}
  function renderHistory(){const list=filterHistory(),body=$('#historyBody');body.replaceChildren();list.forEach(r=>{const e=historicalEmployee(r),st=statusLabel(r),tr=document.createElement('tr');tr.innerHTML=`<td>${escapeHTML(thaiDate(r.date))}</td><td>${escapeHTML(e.code||'—')}</td><td>${escapeHTML(e.name)}</td><td>${escapeHTML(e.department||'—')}</td><td>${timeCell(r,'in')}</td><td>${timeCell(r,'out')}</td><td>${escapeHTML(duration(r))}</td><td>${escapeHTML(r.lateReason||'—')}</td><td><span class="status-pill ${statusClass(st)}">${escapeHTML(st)}</span></td>`;body.append(tr);});$('#historyEmpty').hidden=list.length>0;}
  function reportRows(){const day=$('#reportDate').value||todayISO();return employees.map(e=>{const records=dayRecords(day,e.id),r=records[records.length-1]||null,first=records[0]||null,last=records[records.length-1]||null,minutes=records.reduce((n,x)=>n+durationMinutes(x),0),working=records.some(x=>!x.checkOut);return{e,r,records,first,last,minutes,working};});}
  function minutesText(minutes){return `${Math.floor(minutes/60)} ชม. ${minutes%60} นาที`;}
  function reportStatus(row){return !row.r?'ยังไม่เข้างาน':`${row.working?'เข้างานแล้ว':'ออกงานแล้ว'}${isLate(row.first)?' · มาสาย':''}`;}
  function renderReport(){const day=$('#reportDate').value||todayISO(),dept=$('#reportDepartment').value;$('#reportDateLabel').textContent=thaiDate(day,{weekday:'long'});const rows=reportRows().filter(({e})=>!dept||e.department===dept),present=rows.filter(x=>x.r),minutes=rows.reduce((n,x)=>n+x.minutes,0);$('#reportPresent').textContent=present.length;$('#reportAbsent').textContent=rows.length-present.length;$('#reportHours').textContent=minutesText(minutes);const body=$('#reportBody');body.replaceChildren();rows.forEach(row=>{const {e,minutes:firstMinutes,first,last,working}=row,workText=firstMinutes?`${minutesText(firstMinutes)}${working?' + ยังไม่ออก':''}`:working?'ยังไม่ออก':'—',tr=document.createElement('tr');tr.innerHTML=`<td><b>${escapeHTML(e.code)}</b></td><td>${escapeHTML(e.name)}</td><td>${escapeHTML(e.department)}</td><td>${timeCell(first,'in')}</td><td>${timeCell(last,'out')}</td><td>${escapeHTML(workText)}</td><td><span class="status-pill ${statusClass(reportStatus(row))}">${escapeHTML(reportStatus(row))}</span></td>`;body.append(tr);});$('#reportEmpty').hidden=rows.length>0;}
  function leaveDays(a,b){return Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000)+1;}
  function leaveRequestsForDay(day,department,excludeId=''){return leaves.filter(x=>x.id!==excludeId&&x.status!=='ไม่อนุมัติ'&&x.start<=day&&x.end>=day&&employee(x.employeeId)?.department===department);}
  function departmentHasCoverage(employeeId,start,end,excludeId=''){const person=employee(employeeId);if(!person)return false;const members=employees.filter(x=>x.status==='active'&&x.department===person.department);if(!members.length)return false;for(let d=new Date(`${start}T12:00:00`);d<=new Date(`${end}T12:00:00`);d.setDate(d.getDate()+1)){const day=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,offIds=new Set(leaveRequestsForDay(day,person.department,excludeId).map(x=>x.employeeId));offIds.add(employeeId);if(!members.some(x=>!offIds.has(x.id)))return false;}return true;}
