  function saveStamp(id,type,lateReason=''){const e=employee(id);if(!e){showToast('กรุณาเลือกรหัสพนักงานก่อน',true);return;}if(e.status!=='active'){showToast('พนักงานรายนี้ไม่ได้อยู่ในสถานะปฏิบัติงาน',true);return;}const day=todayISO(),r=currentRecord(id,day),open=openRecord(id);if(type==='in'){if(open){showToast('พนักงานมีรอบลงเวลาที่ยังไม่ได้ออกงาน',true);return;}if(r){showToast('พนักงานลงเวลาออกงานวันนี้แล้ว เริ่มรอบใหม่ได้ในวันถัดไป',true);return;}const checkIn=new Date().toISOString(),record={id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,employeeId:id,employeeCode:e.code,employeeName:e.name,department:e.department,workStart:resolvedStart(e),workEnd:e.workEnd||'',shiftName:e.shiftName||'',workMode:e.workMode||'สำนักงาน',date:day,checkIn,checkOut:null,lateReason:String(lateReason||'').trim()};attendance.push(record);showToast(`บันทึกเวลาเข้างานของ ${e.name} แล้ว`);}else{if(!open){showToast(r?'พนักงานลงเวลาออกงานของวันนี้แล้ว':'ไม่สามารถออกงานได้ เนื่องจากยังไม่มีเวลาเข้างาน',true);return;}open.checkOut=new Date().toISOString();showToast(`บันทึกเวลาออกงานของ ${e.name} แล้ว`);}saveAll();if(type==='in'){$('#homeAttendanceNote').value='';$('#attendanceNote').value='';}renderAll();}
