  $('#leaveBody').addEventListener('click',ev=>{if(!isHRSession())return;const approve=ev.target.closest('[data-leave-approve]'),reject=ev.target.closest('[data-leave-reject]');if(approve)decideLeaveRequest(approve.dataset.leaveApprove,true);else if(reject)openLeaveRejectDialog(leaves.find(x=>x.id===reject.dataset.leaveReject));});$('#leaveCalendarBody').addEventListener('click',ev=>{if(!isHRSession())return;const approve=ev.target.closest('[data-calendar-approve]'),reject=ev.target.closest('[data-calendar-reject]');if(approve)decideLeaveRequest(approve.dataset.calendarApprove,true);else if(reject)openLeaveRejectDialog(leaves.find(x=>x.id===reject.dataset.calendarReject));});$('#closeLeaveReject').addEventListener('click',()=>closeDialog($('#leaveRejectDialog')));$('#cancelLeaveReject').addEventListener('click',()=>closeDialog($('#leaveRejectDialog')));$('#leaveRejectForm').addEventListener('submit',ev=>{ev.preventDefault();const id=$('#leaveRejectId').value,reason=$('#leaveRejectReason').value.trim();if(!reason){showToast('กรุณาระบุเหตุผลที่ไม่อนุมัติ',true);return;}decideLeaveRequest(id,false,reason);if(leaves.find(x=>x.id===id)?.status==='ไม่อนุมัติ'){closeDialog($('#leaveRejectDialog'));$('#leaveRejectForm').reset();}});
